using ThreeDS.Progressive.Services;
namespace ThreeDS.Progressive;
internal sealed record TourStep(string Title,string Text);
internal sealed record TourTopic(string Route,string Title,IReadOnlyList<TourStep> Steps);
internal static class GuidanceCatalog
{
    internal static readonly IReadOnlySet<string> SimpleRoutes=new HashSet<string>{"Pokemon","Trainers","Encounters","StaticEncounters","Moves","LevelUp","MachineTutor","FieldItems","Marts","Evolutions","History","Configuration"};
    internal static readonly IReadOnlyList<TourTopic> Topics=Build();
    private static IReadOnlyList<TourTopic> Build()
    {
        var topics=new List<TourTopic>();
        void Add(string route,string title,string first,string second,string last)=>topics.Add(new(route,title,[new("Qué encontrarás",first),new("Opciones y subsecciones",second),new("Antes de continuar",last)]));
        Add("Home","Inicio y modos","Modo simplificado reúne las secciones principales. Modo completo conserva todas las herramientas.","Puedes cambiar de modo desde Inicio sin volver a extraer la ROM. Randomizado guiado prepara las decisiones paso a paso.","Abrí un proyecto extraído. La ayuda es opcional y se puede cerrar en cualquier momento; F1 vuelve a abrirla en la sección actual.");
        Add("Pokemon","Pokémon","Elegí una especie o forma en la lista. La búsqueda acepta nombre o número.","Estadísticas y tipos están arriba; habilidades, objetos y compatibilidad se agrupan más abajo. Randomizar Pokémon abre opciones por lote; Modificar Pokémon conserva valores exactos.","Guardar confirma una edición manual y la registra. Una vista previa no modifica los archivos hasta que la aplicas.");
        Add("Trainers","Entrenadores","La lista identifica entrenadores; el editor muestra su equipo y propiedades.","La randomización incluye especies, niveles, movimientos, objetos e IA según el juego. Las tablas de caps y reglas de movimientos permiten ajustar entrenadores concretos.","Revisa alcance y vista previa. Las ediciones manuales se registran para conservar equipos exactos en templates.");
        Add("Encounters","Encuentros","Seleccioná una zona y su tabla de encuentros salvajes.","Especies, niveles, formas y SOS dependen de la generación. Wild Gen7 permite configurar rangos y usar su template propio.","Comprobá área, alcance y propuesta antes de aplicar. Copiar una tabla no equivale a randomizar todas las zonas.");
        Add("StaticEncounters","Encuentros estáticos","Aquí se editan encuentros especiales, regalos e iniciales compatibles.","Los filtros separan regalos, estáticos y otras categorías. Gen7 añade opciones de Totem; las restricciones dependen del juego.","Para cambiar solo iniciales, revisa el alcance de regalos y evita incluir categorías que quieras conservar.");
        Add("Moves","Movimientos","Elegí el movimiento cuyo poder, precisión, PP, tipo o categoría quieras editar.","Randomizar y modificar son acciones diferentes. Los templates pueden incluir descripciones y BattlePatch compatibles.","Previsualiza los cambios y guarda cuando coincidan con lo que buscas. Cambiar datos del movimiento no cambia su aprendizaje por nivel.");
        Add("LevelUp","Level Up Moves","La lista de especies abre sus movimientos aprendidos por nivel.","Puedes añadir, editar y quitar entradas. La randomización tiene STAB, expansión de cantidad y distribución de niveles.","Revisa la tabla propuesta y aplica. Las ediciones manuales conservan niveles y movimientos exactos en el historial.");
        Add("MachineTutor","MT y tutores","Este editor trabaja con las MT y los tutores disponibles para la generación.","Randomizar cambia el movimiento asignado. Sanity y Follow Evolutions trabajan con compatibilidad; no son el mismo ajuste.","Una MT fija se edita a mano. Comprueba las opciones recordadas para Global/Batch si quieres repetir el comportamiento en otras ROMs.");
        Add("Items","Objetos y economía","Edita propiedades de objetos, incluidos precios y otras referencias disponibles.","La tabla de economía y los presets complementan las ediciones individuales. Tiendas controla inventarios, Field Items controla objetos del mapa.","Compara propuesta y precio antes de aplicar; el precio normal y el coste BP pueden proceder de tablas distintas.");
        Add("Marts","Tiendas","Las tiendas disponibles dependen de XY, ORAS, SM o USUM.","En Gen7 los botones de tiendas y BP generan opciones acumulables. Puedes añadir caramelos, vitaminas y otras acciones compatibles.","Revisa Cambios previstos. Aplicar guarda la propuesta; elegir opciones para Global/Batch no reconstruye por sí solo una ROM.");
        Add("FieldItems","Field Items","Son los objetos recogidos en el mapa, incluidos los ocultos compatibles.","Los catálogos permitidos y prohibidos controlan el pool. Los filtros de MT y objetos clave ayudan a delimitar la selección.","Confirma alcance y catálogo antes de aplicar. No confundas objetos de campo con la habilidad Recogida (Pickup).");
        Add("Evolutions","Evoluciones","Cada especie puede tener varias rutas con destino, método y argumento.","El argumento depende del método: objeto, especie u otro valor. Los templates usan IDs para conservar compatibilidad entre idiomas.","Elige entre motores originales y ajustes personalizados. Comprueba las rutas antes de guardar o aplicar un template.");
        Add("GameText","Game Text","Busca una frase o abre un banco de textos del juego.","El idioma seleccionado y el banco determinan lo que editas. Comandos/variables explica los marcadores que usa el juego.","Conserva los comandos necesarios y revisa la vista previa cuando esté disponible. Guardar afecta al texto elegido, no a todos los idiomas.");
        Add("StoryText","Story Text · diálogos","Contiene textos vinculados a escenas y eventos de la historia.","Las etiquetas ayudan a localizar bancos; la búsqueda por frase evita recorrerlos uno a uno. Consulta comandos antes de cambiar variables.","Una descripción larga puede necesitar saltos de línea. No elimines marcadores de control sin conocer su función.");
        Add("Mechanics","Mecánicas y CRO","Reúne modificaciones de comportamiento compatibles con el juego abierto.","Las recetas CRO, caps y Relearner tienen editores propios. Las herramientas específicas no aparecen para juegos incompatibles.","Revisa firmas, dependencias y vista previa. Conserva una copia antes de aplicar parches de comportamiento.");
        Add("PokemonTools","Herramientas Pokémon","Agrupa operaciones masivas y editores relacionados con Pokémon.","Puedes abrir compatibilidad, movimientos huevo, megaevoluciones y otras funciones disponibles.","Las herramientas conservan sus propias confirmaciones y alcance. El modo simplificado no elimina los datos ni sus funciones.");
        Add("RomTools","Herramientas ROM","Agrupa extracción, reconstrucción y recursos de la ROM.","Rebuild también está junto a Generar backup. Las herramientas de icono, títulos y restauración se abren desde sus tarjetas.","Trabaja con proyectos extraídos y salidas distintas. Generar un backup no equivale a reconstruir una ROM jugable.");
        Add("Automation","Automatización","Aquí se agrupan herramientas para repetir procesos.","Global Template conserva una receta; Batch ROM Builder la ejecuta sobre copias aisladas. El asistente guiado genera una ROM por recorrido.","Comprueba juego, acciones y dependencias de la receta antes de construir varias ROMs.");
        Add("Configuration","Opciones e idioma","Cambia preferencias y el idioma de los datos del juego.","Recargar idioma vuelve a leer los catálogos. Las etiquetas de la interfaz y los textos almacenados son conceptos distintos.","Cambiar idioma no traduce ni modifica automáticamente la ROM. Guarda las ediciones antes de recargar.");
        Add("TemplateStudio","Templates","Elige el tipo de template que quieres crear o editar.","Las tablas de movimientos, evoluciones y estadísticas usan selectores por ID. Field Items y tiendas tienen catálogos y reglas propios.","Exportar guarda el archivo; Usar template lo incorpora al flujo y al historial. Sus dependencias deben acompañar al Global Template.");
        Add("GlobalTemplate","Global Template","Una receta reúne acciones, opciones y dependencias reproducibles.","Puedes cargar, revisar y exportar acciones. Los cambios manuales exactos se reproducen al final; las acciones aleatorias usan su política de semillas.","El historial es un registro pasado: comprueba su estado si se restauraron archivos. Valida los assets antes de usar Batch.");
        Add("BatchRom","Batch ROM Builder","Construye una o varias ROMs desde una receta validada.","Elige salida, nombre, cantidad y opciones de reconstrucción. La comprobación previa detecta acciones o assets incompatibles.","Cada ROM usa su copia aislada y genera resultados de integridad. La verificación no sustituye una prueba en el juego.");
        Add("History","Historial de cambios","Conserva la secuencia de operaciones guardadas, parámetros y archivos.","La comprobación SHA-256 distingue registros coherentes, desfasados y sin comprobación binaria. Puedes repetirla con el botón de comprobar.","Limpiar archivos no borra el registro histórico. Los registros desfasados no demuestran cambios presentes en la ROM actual.");
        Add("Rebuild","Rebuild","Empaqueta el estado guardado actual en RomFS, ExeFS o .3DS.","Elige tipo y destino. Después aparece una confirmación con el historial contrastado; no se vuelven a randomizar sus acciones.","No empaqueta ediciones sin guardar. Al terminar muestra tamaño y SHA-256 del archivo generado.");
        Add("Extraction","Extraer ROM","Selecciona una ROM compatible y una carpeta nueva para extraer.","El proyecto necesita sus carpetas RomFS y ExeFS; el ExHeader es necesario para reconstruir un .3DS.","La extracción puede tardar. Abre el proyecto terminado antes de editarlo.");
        Add("Pickup","Pickup","Edita los objetos de la habilidad Recogida.","Puedes revisar objetos, probabilidades y propuesta de randomización según el juego.","Aplica la propuesta desde este editor; el asistente usa el mismo flujo compatible de replay.");
        Add("ShinyRate","Shiny Rate","Ajusta los rerolls compatibles del juego.","La opción de todo shiny es distinta de aumentar las probabilidades. La propuesta comprueba el ejecutable antes de aplicar.","Revisa los valores elegidos y su compatibilidad; guarda antes de reconstruir.");
        Add("PlayerCaps","Player Level Caps","Configura los checkpoints de caps compatibles con USUM.","Las condiciones usan flags y Event Work. La sincronización de entrenadores es una operación adicional.","Revisa condiciones y propuesta conjunta antes de aplicar los parches.");
        Add("CroRecipes","CRO Recipes","Importa recetas de mecánicas para el juego compatible.","Dependencias, firmas y relocaciones se comprueban antes de preparar la propuesta.","Aplicar confirma los cambios conjuntos; una receta incompatible se rechaza.");
        Add("UsumRelearner","USUM Relearner","Configura el parche de aprendizaje y cafeterías de USUM.","La vista previa incluye los recursos implicados y comprueba las firmas conocidas.","Confirma la propuesta y revisa el historial antes del Rebuild.");
        Add("EggMoves","Egg Moves","Edita los movimientos heredados por crianza.","La randomización permite controlar cantidad y filtros de movimientos compatibles.","Guardar una lista manual conserva su orden y contenido como una edición exacta.");
        Add("MegaEvolutions","Megaevoluciones","Edita los slots de megaevolución y sus condiciones.","El editor manual y el desbloqueo compatible son operaciones distintas.","No se randomizan automáticamente slots por abrir esta herramienta; revisa cada propuesta.");
        Add("TypeChart","Tabla de tipos","Muestra las relaciones de eficacia entre tipos.","Elige la relación que quieres modificar y revisa su valor.","Aplica solo después de comprobar la tabla resultante y conserva un backup.");
        Add("Tutor6","Tutores BP · ORAS","Edita movimientos y precios de los tutores de ORAS.","La compatibilidad y la oferta de movimientos se configuran por separado.","Revisa ambas tablas si quieres cambiar qué se enseña y qué Pokémon puede aprenderlo.");
        Add("Trade6","Intercambios · Gen6","Configura las ofertas y condiciones de los intercambios compatibles.","Randomizar las ofertas es distinto de aceptar cualquier especie del jugador.","Comprueba la propuesta y el alcance antes de guardar.");
        Add("CatchZones","Catch Zones","Configura las zonas de captura y sus parches compatibles.","Los recursos y el manifiesto determinan dónde se aplica la función.","Usa la comprobación previa y no traslades offsets entre juegos.");
        Add("OPower","O-Powers","Edita los efectos de O-Powers en Gen6.","Elige una entrada y comprueba los rangos disponibles.","Guarda los valores exactos y revisa el historial de la operación.");
        Add("PersistentItems","Persistent Items","Configura los consumibles persistentes compatibles con USUM.","Revisa la lista de objetos y los recursos afectados por el parche.","Confirma únicamente tras revisar firmas y vista previa.");
        Add("CroIntegrity","Integridad CRO/CRR","Comprueba los módulos CRO y sus referencias de integridad.","La comprobación identifica archivos y firmas que requieren atención.","No sustituye los hashes de una receta para ocultar diferencias de contenido.");
        Add("RestoreSelected","Restaurar archivos","Restaura solo los recursos seleccionados desde una copia válida.","Compara origen, destino y archivos que se van a reemplazar.","Después vuelve a comprobar el historial: un registro antiguo puede quedar desfasado.");
        foreach(var route in new[]{"FacilityNormal","FacilityAlternate"})Add(route,route=="FacilityNormal"?"Instalaciones · Normal":"Instalaciones · Alternativa","Edita entrenadores y Pokémon de la instalación disponible para el juego.","Selecciona la modalidad y revisa equipos, movimientos e inventarios expuestos.","Estas tablas son distintas de los entrenadores de la historia. Guarda la edición correspondiente.");
        foreach(var route in new[]{"TitleScreen6","TitleScreen7","SMDH","Graphics","GarcShuffle","OWSE"})Add(route,route switch{"SMDH"=>"Icono SMDH","Graphics"=>"Gráficos","GarcShuffle"=>"GARC Shuffle","OWSE"=>"OWSE",_=>"Pantalla de título"},"Esta herramienta trabaja con recursos específicos del juego o del proyecto.",route switch{"SMDH"=>"Revisa icono y metadatos antes de exportar.","Graphics"=>"Importa o inspecciona los formatos gráficos admitidos.","GarcShuffle"=>"Selecciona archivos y alcance de la reorganización compatible.","OWSE"=>"Es una herramienta de desarrollo: comprueba la función concreta antes de usarla.",_=>"Revisa las imágenes o recursos de título compatibles con la generación."},"La importación y la aplicación mantienen sus validaciones propias. Conserva una copia de los recursos originales.");
        return topics;
    }
    internal static TourTopic Find(string route)=>Topics.FirstOrDefault(topic=>topic.Route==route)??Topics[0];
    internal static IReadOnlyList<TourTopic> Available(GameProjectSession? project)=>Topics.Where(topic=>project is null?topic.Route=="Home"||topic.Route=="Extraction":ProjectFeatureAvailability.Supports(project,topic.Route)).ToArray();
}
